{
  "title": "The Gilded Chain Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined gates.",
      "visual_description": "Crumbling stone gates flanked by broken statues, tattered royal banners flutter in the wind.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn of the curse.",
      "visual_description": "Huddled figures in rags point toward a twisted black tower, eyes wide with fear.",
      "characters": ["Kaelen", "Mira", "Torvin", "Elder Hestia"]
    },
    {
      "scene_number": 3,
      "caption": "An armored patrol blocks the main road.",
      "visual_description": "Four soldiers in rusted plate armor stand in formation, halberds crossed before a stone arch.",
      "characters": ["Kaelen", "Mira", "Torvin", "Sergeant Vance", "Patrol Guard"]
    },
    {
      "scene_number": 4,
      "caption": "They slip through a side alley to avoid conflict.",
      "visual_description": "Narrow alley lined with fallen timbers, a stray cat darts past a flickering lantern.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 5,
      "caption": "A cursed tower looms before them.",
      "visual_description": "Obsidian tower with glowing blue runes, a spiral staircase visible through a shattered window.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 6,
      "caption": "Mira disarms a rune trap on the tower door.",
      "visual_description": "Mira crouches by the door, fingers tracing a circle of runes, a faint hum in the air.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 7,
      "caption": "Inside, a phantom dragon's roar echoes.",
      "visual_description": "Vast circular chamber with a mosaic floor, a ghostly dragon shape swirls in the dust motes.",
      "characters": ["Kaelen", "Mira", "Torvin"]
    },
    {
      "scene_number": 8,
      "caption": "They find a captive in an iron cage.",
      "visual_description": "Iron cage suspended from chains, a young woman in torn clothes reaches through the bars.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 9,
      "caption": "Kaelen picks the cage lock while Torvin stands watch.",
      "visual_description": "Kaelen works a thin pick into the lock, Torvin grips his axe staring down the dark corridor.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 10,
      "caption": "Mira triggers a magical door alarm.",
      "visual_description": "A shimmering door pulses red, a bell-like clang resonates through the tower.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols swarm the tower base.",
      "visual_description": "Soldiers pour through the main gate, torches lighting their helmets, sergeant shouting orders.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra", "Sergeant Vance", "Patrol Guard"]
    },
    {
      "scene_number": 12,
      "caption": "They escape via a rooftop passage.",
      "visual_description": "Cracked tiles underfoot, a rope bridge stretched between two parapets, wind howling.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 13,
      "caption": "A drake circles overhead.",
      "visual_description": "Scaly silhouette against the moon, leathery wings spread, a low growl rumbles from above.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra", "Drake"]
    },
    {
      "scene_number": 14,
      "caption": "Torvin distracts the drake with a shout.",
      "visual_description": "Torvin waves his axe and bellows, the drake banks toward him, talons extended.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra", "Drake"]
    },
    {
      "scene_number": 15,
      "caption": "They dash through the old market square.",
      "visual_description": "Overturned carts and rotting awnings, faded royal crest painted on a collapsed fountain.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 16,
      "caption": "The escape bridge is partially collapsed.",
      "visual_description": "Stone bridge with a missing central span, ropes and planks from a makeshift repair dangle over a chasm.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 17,
      "caption": "Mira creates a magical plank to cross.",
      "visual_description": "Mira extends her hands, a shimmering translucent bridge forms over the gap, sparks at her fingertips.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    },
    {
      "scene_number": 18,
      "caption": "They cross and the bridge collapses behind them.",
      "visual_description": "Final leap onto solid ground, the magical plank dissolves, stone and rope tumble into the misty chasm.",
      "characters": ["Kaelen", "Mira", "Torvin", "Lyra"]
    }
  ]
}

